from collections import Counter

def orf_finder(seq, min_len=90):
    """Find ORFs (ATG..stop) in all 6 frames."""
    stops = {'TAA','TAG','TGA'}
    orfs = []
    L = len(seq)
    for strand, s in [('+', seq), ('-', seq[::-1].translate(str.maketrans('ACGT','TGCA')))]:
        for frame in range(3):
            i = frame
            start = None
            while i + 3 <= L - (L - frame) % 3:
                codon = s[i:i+3]
                if codon == 'ATG' and start is None:
                    start = i
                elif codon in stops:
                    if start is not None:
                        aas = (i - start)//3
                        if aas >= min_len//3:
                            orfs.append((strand, frame, start, i, aas))
                    start = None
                i += 3
    return orfs

