# Simple approach: find long inverted repeats (IRs, allowing small loop)
def find_ir(seq, min_stem=12, max_gap=6):
    found = []
    L = len(seq)
    for i in range(L):
        for stem_len in range(min_stem, min(30, (L - i)//2)+1):
            left = seq[i:i+stem_len]
            right_rc = revcomp(seq[i+stem_len+0 : i+stem_len+max_gap+len(left)])
            if left == right_rc[:stem_len]:
                found.append((i+1, i+stem_len, i+stem_len+1, i+2*stem_len, stem_len))
    return found

