import re
def find_dr(seq, min_len=14):
    drs = []
    L = len(seq)
    for k in range(min_len, 25):
        for i in range(L - 2*k):
            if seq[i:i+k] == seq[i+k:i+2*k]:
                drs.append((i+1, i+k, i+k+1, i+2*k))
    return drs

